import { Component, Event, EventEmitter, h, Host, Prop } from '@stencil/core';
import { Heading, VWGroupHeadlineFontVariant } from '../../types';

/**
 * @slot default - default slot for the text of the headline
 */
@Component({
  tag: 'groupui-headline',
  styleUrl: 'headline.scss',
  shadow: true,
})
export class Headline {
  /**
   * heading type of the headline
   */
  @Prop({ reflect: true }) readonly heading: Heading = 'h1';

  /**
   * style attribute
   */
  @Prop({ reflect: true }) readonly weight;

  /**
   * style attribute
   */
  @Prop({ reflect: true }) readonly serif: boolean;

  /**
   * Application type is product by default. Changes the application type to marketing.
   */
  @Prop({ reflect: true }) readonly marketing: boolean;

  /**
   * style attribute
   */
  @Prop({ reflect: true }) readonly fontVariant: VWGroupHeadlineFontVariant = 'TheGroupTEXT-Bold';

  /**
   * dispatched when component finished loading
   */
  @Event({ bubbles: false }) groupuiDidLoad: EventEmitter<void>;

  componentDidLoad() {
    this.groupuiDidLoad.emit();
  }

  render() {
    return (
      <Host>
        <this.heading>
          <slot></slot>
        </this.heading>
      </Host>
    );
  }
}
